// SQL & Database Fundamentals — Part 3 (q601–720)
window.QUIZ_BANK['sql-db'] = (window.QUIZ_BANK['sql-db']||[]).concat([
{id:601,topic:'sql-db',difficulty:'beginner',question:'Which SQL function returns the absolute value of a number?',options:['ABS()','ABSOLUTE()','POSITIVE()','MOD()'],answer:0,explanation:'ABS(x) returns the absolute (non-negative) value of x: ABS(-5) = 5, ABS(5) = 5.'},
{id:602,topic:'sql-db',difficulty:'beginner',question:'What does MOD() or the % operator do?',options:['Multiplies two numbers','Returns the remainder after dividing one number by another','Returns the modulus (absolute value)','Performs modular encryption'],answer:1,explanation:'MOD(dividend, divisor) / (dividend % divisor) returns the remainder of integer division: MOD(10, 3) = 1.'},
{id:603,topic:'sql-db',difficulty:'beginner',question:'What is the IN operator equivalent to in terms of OR conditions?',options:['col = val1 AND col = val2','col = val1 OR col = val2 OR col = val3 (for IN (val1, val2, val3))','col BETWEEN val1 AND val3','col LIKE val1'],answer:1,explanation:'IN (v1, v2, v3) is functionally equivalent to (col = v1 OR col = v2 OR col = v3) but more concise and readable.'},
{id:604,topic:'sql-db',difficulty:'beginner',question:'What happens to a subquery when it is placed in the FROM clause?',options:['It acts as a table alias','It is treated as a derived table (inline view), producing a result set that the outer query selects from as if it were a real table','It runs after the outer query','It is ignored by the database optimizer'],answer:1,explanation:'A subquery in the FROM clause creates a derived table (inline view); the outer query references it by an alias, joining or filtering against its result set.'},
{id:605,topic:'sql-db',difficulty:'beginner',question:'What is the % wildcard in SQL LIKE?',options:['Matches exactly one character','Matches zero or more characters of any type','Matches numeric digits only','Matches special characters only'],answer:1,explanation:'The % wildcard matches any sequence of zero or more characters: LIKE \'A%\' matches strings starting with A; LIKE \'%test%\' matches strings containing "test" anywhere.'},
{id:606,topic:'sql-db',difficulty:'beginner',question:'What is the _ wildcard in SQL LIKE?',options:['Matches zero or more characters','Matches exactly one single character','Matches any whitespace character','Matches any uppercase character'],answer:1,explanation:'The _ wildcard matches exactly one character: LIKE \'_at\' matches "cat", "hat", "bat" but not "chat" (two characters before "at").'},
{id:607,topic:'sql-db',difficulty:'beginner',question:'What does IFNULL(expression, value) do in MySQL?',options:['Tests if a table is empty','Returns the expression if it is not NULL, or returns the specified value if the expression IS NULL','Converts NULL to false','Finds and replaces NULL in a whole column'],answer:1,explanation:'IFNULL(expr, alt) is MySQL\'s two-argument null-replacement function: equivalent to COALESCE(expr, alt) and ISNULL(expr, alt) in SQL Server.'},
{id:608,topic:'sql-db',difficulty:'beginner',question:'What is NULLIF(expr1, expr2) used for?',options:['Checks if two expressions are both NULL','Returns NULL if the two expressions are equal; otherwise returns expr1 — useful for preventing division-by-zero errors','Replaces NULL with a default value','Tests for NULL in both expressions'],answer:1,explanation:'NULLIF(a, b) returns NULL if a = b, else returns a. Classic use: NULLIF(denominator, 0) in a division to avoid division-by-zero (result becomes NULL instead of error).'},
{id:609,topic:'sql-db',difficulty:'beginner',question:'What does the DATE_DIFF or DATEDIFF function compute?',options:['Adds a time interval to a date','Returns the number of days (or specified interval units) between two date values','Formats a date as a string','Converts a string to a date'],answer:1,explanation:'DATEDIFF(date1, date2) computes the difference between two dates in days (MySQL: DATEDIFF returns days; SQL Server DATEDIFF requires a date part specification).'},
{id:610,topic:'sql-db',difficulty:'beginner',question:'What is CAST() used for in SQL?',options:['Casting spells in stored procedures','Converting a value from one data type to another explicitly','Comparing two values of different types','Filtering results based on data type'],answer:1,explanation:'CAST(expression AS target_type) explicitly converts a value to a specified data type: CAST(\'123\' AS INT), CAST(salary AS VARCHAR(20)).'},
{id:611,topic:'sql-db',difficulty:'intermediate',question:'What is the purpose of a "junction table" (bridge table)?',options:['A table that connects two databases','A table that resolves a many-to-many relationship between two entities by storing pairs of foreign keys, one referencing each entity','A table that bridges different schemas','A temporary table created during JOIN operations'],answer:1,explanation:'A junction table (e.g., student_course) has two FK columns (student_id, course_id), each referencing the PK of the respective entity table, implementing a many-to-many relationship.'},
{id:612,topic:'sql-db',difficulty:'intermediate',question:'What is "foreign key violation" and what causes it?',options:['A syntax error in a FOREIGN KEY constraint definition','Attempting to INSERT or UPDATE a row with a FK column value that does not exist in the referenced parent table\'s PK column','A duplicate key error in the primary key','A NULL value in a NOT NULL column'],answer:1,explanation:'A FK violation occurs when the FK value has no matching PK in the parent table (orphaned record). Databases with FK constraints reject such DML operations.'},
{id:613,topic:'sql-db',difficulty:'intermediate',question:'What is a "materialised view refresh"?',options:['Refreshing the database server\'s memory','Updating the physical data stored in a materialised view to reflect changes in the underlying base tables, either on demand (REFRESH MATERIALIZED VIEW) or on a scheduled basis','Refreshing the database schema after DDL changes','Reloading indexes on a view'],answer:1,explanation:'Materialised views need periodic refresh (COMPLETE or FAST/INCREMENTAL) to remain current; stale materialised views may serve outdated data — trade-off between freshness and performance.'},
{id:614,topic:'sql-db',difficulty:'intermediate',question:'What is "implicit type conversion" (type coercion) in SQL and when is it problematic?',options:['Automatic conversion between integer types','The database automatically converts one data type to another to satisfy a comparison or expression — problematic when it prevents index use (e.g., WHERE char_col = 1 converts all char values to integers, disabling the index)','Explicit CAST within a stored procedure','Automatic NULL handling'],answer:1,explanation:'Implicit coercion can silently disable indexes: WHERE varchar_col = 123 may convert the indexed varchar column to integer for comparison, forcing a full table scan.'},
{id:615,topic:'sql-db',difficulty:'intermediate',question:'What is "sargable" in query optimisation?',options:['A type of SQL join condition','A predicate that the query optimizer can use an index to satisfy (Search ARGument ABLE) — e.g., WHERE col = value is sargable; WHERE FUNC(col) = value is not (forces full scan)','A table type optimised for storage','A performance hint inserted in the SQL comment'],answer:1,explanation:'Sargable (Search ARGument ABLE) predicates allow index seeks. Non-sargable predicates (WHERE YEAR(date_col) = 2024, WHERE UPPER(name) = \'JOHN\') apply a function to the indexed column, preventing index use.'},
{id:616,topic:'sql-db',difficulty:'intermediate',question:'What is "query rewriting" in the context of query optimisation?',options:['Manually rewriting SQL by a DBA','The optimizer or DBA transforms a semantically equivalent query into a form that executes more efficiently — e.g., replacing NOT IN with NOT EXISTS, subquery to JOIN, or UNION to UNION ALL','Rewriting queries in a different SQL dialect','Replacing stored procedures with views'],answer:1,explanation:'Query rewriting transforms semantically equivalent queries for better execution: NOT IN → NOT EXISTS (handles NULL differently and may use better plan), subquery → JOIN, correlated → non-correlated.'},
{id:617,topic:'sql-db',difficulty:'intermediate',question:'What is the "CASE expression" in SQL?',options:['A conditional branching statement only available in stored procedures','A SQL expression (not a statement) providing conditional logic within a query — CASE WHEN condition THEN result ... ELSE default END','A way to define a SWITCH statement in SQL','A case-sensitivity flag for string comparisons'],answer:1,explanation:'CASE is an expression usable in SELECT, WHERE, ORDER BY, etc.: simple CASE (compare against values) and searched CASE (evaluate boolean conditions). Returns the first matching result.'},
{id:618,topic:'sql-db',difficulty:'intermediate',question:'What is "pivot" in SQL?',options:['Rotating rows to columns','Transforming row values into columns, turning a normalised row-per-category structure into a wide cross-tabulation format — implemented with PIVOT operator (SQL Server) or conditional aggregation','Sorting a result set on a pivot column','Changing the primary key of a table'],answer:1,explanation:'PIVOT (SQL Server) or conditional aggregation (CASE + GROUP BY in standard SQL) rotates a result set: categories in rows become column headers with aggregated values.'},
{id:619,topic:'sql-db',difficulty:'intermediate',question:'What does "INTERSECT" do in SQL?',options:['Finds the intersection of two tables via a JOIN','Returns only the rows that appear in BOTH result sets from two SELECT statements (common rows), removing duplicates','Returns all rows from both result sets including duplicates','Returns rows in the first set but not in the second'],answer:1,explanation:'INTERSECT returns the distinct rows present in both SELECTs\' result sets — analogous to a mathematical set intersection.'},
{id:620,topic:'sql-db',difficulty:'intermediate',question:'What does "EXCEPT" (or MINUS in Oracle) do in SQL?',options:['Returns all rows from both SELECT statements','Returns the distinct rows from the first SELECT that do not appear in the second SELECT result set','Creates an exception handler for SQL errors','Removes specific columns from the result set'],answer:1,explanation:'EXCEPT (standard SQL) / MINUS (Oracle) returns distinct rows from the first query that are NOT present in the second query — analogous to a mathematical set difference.'},
{id:621,topic:'sql-db',difficulty:'intermediate',question:'What is "connection timeout" in database connections?',options:['Maximum time to execute a query','Maximum time the application waits when trying to establish a database connection before failing with an error','Maximum time a transaction can remain open','Maximum time to close a connection'],answer:1,explanation:'Connection timeout is the maximum waiting time for a connection to be established (or obtained from the pool); separate from command/query timeout (max query execution time).'},
{id:622,topic:'sql-db',difficulty:'intermediate',question:'What is "query timeout" in database connections?',options:['The time limit for establishing a connection','Maximum time the database allows a query to execute before automatically cancelling it','Maximum time for a transaction commit','Maximum time the connection remains idle'],answer:1,explanation:'Query (command) timeout sets the maximum execution time for a SQL statement; if exceeded, the query is automatically cancelled and the application receives a timeout error.'},
{id:623,topic:'sql-db',difficulty:'intermediate',question:'What is a "database diagram" or "schema diagram"?',options:['A network topology diagram for database servers','A visual representation of tables, their columns, data types, primary keys, foreign keys, and relationships in a database schema','A flowchart showing stored procedure execution','A Gantt chart for database migration projects'],answer:1,explanation:'A database (schema) diagram visualises the complete structure: tables, columns with types, PKs highlighted, FK lines showing relationships, and cardinality notation.'},
{id:624,topic:'sql-db',difficulty:'intermediate',question:'What is "lazy loading" in the context of ORM and databases?',options:['Loading only the visible portion of a dataset','Deferring the loading of related entities until they are explicitly accessed in code, generating additional SQL queries on demand rather than loading all related data upfront','A technique for slow databases to defer expensive operations','Loading test data lazily for performance tests'],answer:1,explanation:'Lazy loading in ORMs loads related entities only when accessed in code; while convenient, it can trigger the N+1 problem. Eager loading explicitly joins and loads related data in one query.'},
{id:625,topic:'sql-db',difficulty:'intermediate',question:'What is "eager loading" in ORM?',options:['Loading data as quickly as possible using index hints','Pre-loading related entities in the same query using JOINs or subsequent batch queries, preventing the N+1 problem but potentially loading unnecessary data','Loading all database tables into memory on startup','An ORM feature that pre-caches frequently queried rows'],answer:1,explanation:'Eager loading (JOIN FETCH in JPA, Include() in Entity Framework, preload() in ActiveRecord) loads related entities upfront in one or two queries, avoiding the N+1 problem at the cost of potentially larger result sets.'},
{id:626,topic:'sql-db',difficulty:'intermediate',question:'What is a "composite index" and when should you use one?',options:['An index combining multiple tables','An index on two or more columns; useful when queries frequently filter or sort on multiple columns together — column order matters for index effectiveness','An index that combines clustered and non-clustered strategies','An index that automatically adapts to query patterns'],answer:1,explanation:'Composite indexes are most effective when queries filter on all (or a leading prefix of) the indexed columns. Column order matters: equality predicates first, then range predicates.'},
{id:627,topic:'sql-db',difficulty:'intermediate',question:'What is the "leftmost prefix rule" for composite indexes?',options:['The leftmost table in a JOIN benefits most from the index','A composite index (a, b, c) can be used by queries filtering on a, or a+b, or a+b+c — but NOT b alone or c alone, because the index tree must be traversed from the leftmost column','Only the first column in a composite index can be queried','The leftmost column is always the primary key'],answer:1,explanation:'The leftmost prefix rule: the optimizer can use a composite index (a, b, c) for predicates on (a), (a, b), or (a, b, c) — not for predicates on (b) or (c) alone, as the tree is ordered on the leftmost key first.'},
{id:628,topic:'sql-db',difficulty:'advanced',question:'What is a "hash join" algorithm and when does the optimizer choose it?',options:['A join using hash-based FK constraints','An algorithm that builds a hash table from the smaller table, then probes it for each row from the larger table — preferred when joining large unsorted datasets without usable indexes','A join that hashes the join key for encryption','A join that combines hash indexes from both tables'],answer:1,explanation:'Hash join: build a hash table from the smaller (build) table on the join key; scan the larger (probe) table, hashing each row to find matches. Efficient for large, unsorted, non-indexed joins.'},
{id:629,topic:'sql-db',difficulty:'advanced',question:'What is a "nested loop join" and when is it preferred?',options:['A join algorithm for recursive queries','For each row in the outer (driving) table, scan the inner table for matching rows — efficient when the outer table is small and the inner table has an index on the join column','A join that loops through all columns','A join that joins more than two tables simultaneously'],answer:1,explanation:'Nested loop join: O(N×M) in the worst case, but with an index on the inner table it becomes O(N log M) — optimal when one input is small and the other is large with a selective index.'},
{id:630,topic:'sql-db',difficulty:'advanced',question:'What is a "merge join" (sort-merge join) algorithm?',options:['A join that merges two schemas','Both input tables are sorted on the join key; then a single linear merge pass matches equal keys — efficient for large pre-sorted or indexed tables but requires a sort step if data is not sorted','A join that merges result sets from UNION','A join used only for FULL OUTER JOIN operations'],answer:1,explanation:'Sort-merge join: sort both inputs on join key → merge linearly (O(N+M) after sorting). Efficient when inputs are already sorted (index-ordered access), avoiding the hash table build cost.'},
{id:631,topic:'sql-db',difficulty:'advanced',question:'What is "query plan instability" (plan regression) in production databases?',options:['When query plans are printed unstably to the log','When a previously optimal execution plan is replaced by a less efficient plan due to statistics changes, system changes, or optimizer upgrades — causing sudden performance degradation','When two queries compete for the same execution plan slot','When the execution plan cannot be cached'],answer:1,explanation:'Plan regression occurs when statistics or system changes cause the optimizer to choose a suboptimal plan; solutions include forcing plans (USE PLAN, BASELINE, hint), refreshing statistics, or configuring Automatic Plan Correction (SQL Server).'},
{id:632,topic:'sql-db',difficulty:'advanced',question:'What is "page splitting" in a B-tree index and why does it impact performance?',options:['When the database page size configuration is changed','When a new row is inserted into a full B-tree index page, requiring the page to be split into two pages (50% full each) — increasing fragmentation, degrading sequential access, and requiring extra I/O','When a table is split into multiple partitions','When a page in memory is swapped out to disk'],answer:1,explanation:'Page splits occur during out-of-order inserts into B-tree indexes; they leave pages ~50% full (wasted space), increase fragmentation, and can cascade to parent pages — an argument for sequential keys.'},
{id:633,topic:'sql-db',difficulty:'advanced',question:'What is "WAL" (Write-Ahead Logging) and why is it critical for ACID durability?',options:['A logging protocol for web application requests','A technique where all changes are written to a transaction log (WAL) before they are applied to data pages, ensuring that committed transactions survive crashes and enabling point-in-time recovery','A way of writing all queries before execution','A log of all read operations on the database'],answer:1,explanation:'WAL ensures durability: changes are first persisted to the sequential log (fast sequential I/O), then applied to data pages. On crash recovery, the log is replayed to restore committed changes not yet in data pages.'},
{id:634,topic:'sql-db',difficulty:'advanced',question:'What is "point-in-time recovery" (PITR) in databases?',options:['Recovering to the exact time a backup was created','Using full backups plus continuous WAL/transaction log backups to restore the database to any specific point in time, enabling recovery from data corruption or accidental deletion','Recovering the most recent point-in-time of a query cache','Restoring only the most recent changes'],answer:1,explanation:'PITR combines a base backup with WAL segment archives; the database can be restored to any past point in time by replaying the log from the base backup to the desired recovery target timestamp.'},
{id:635,topic:'sql-db',difficulty:'advanced',question:'What is "checkpoint" in database recovery?',options:['A point in testing where the database is verified','A periodic operation where the database engine flushes dirty pages from the buffer pool to disk and records a log sequence number, reducing crash recovery time by limiting how far back in the log recovery must replay','A transaction commit point','A scheduled database backup point'],answer:1,explanation:'Checkpoints limit crash recovery time by flushing dirty buffer pages to disk and recording the WAL position; recovery only replays WAL from the last checkpoint, not from the beginning of time.'},
{id:636,topic:'sql-db',difficulty:'advanced',question:'What is "MVCC" (Multi-Version Concurrency Control) in PostgreSQL?',options:['A version control system for database schema changes','PostgreSQL maintains multiple versions of rows (tuples) for concurrent transactions — each transaction sees a consistent snapshot (based on transaction ID) without blocking other transactions, enabling high concurrency without readers blocking writers','A method for multi-version SQL syntax support','A technique for versioning stored procedures'],answer:1,explanation:'PostgreSQL\'s MVCC never overwrites data in-place; old row versions remain until VACUUM removes them (dead tuples). Each transaction\'s snapshot is determined by transaction IDs, providing isolation without locking.'},
{id:637,topic:'sql-db',difficulty:'advanced',question:'What is "VACUUM" in PostgreSQL and why is it necessary?',options:['A tool for clearing database caches','A maintenance operation that removes dead tuples (old row versions no longer visible to any transaction) left by MVCC, reclaims storage, updates statistics, and prevents transaction ID wraparound','A database schema cleanup tool','A technique for deleting rows without logging'],answer:1,explanation:'PostgreSQL MVCC creates dead tuples on UPDATE/DELETE; VACUUM reclaims their space, maintains statistics for the optimizer, and critically prevents transaction ID wraparound (a potential data loss scenario after 2^31 transactions).'},
{id:638,topic:'sql-db',difficulty:'advanced',question:'What is "connection pool exhaustion" and how does it manifest?',options:['A pool of database files becoming full','When all connections in the pool are in use and no new connections can be allocated, causing application requests to queue or fail with "connection pool exhausted" errors — often caused by long-running queries holding connections','When the database runs out of storage space','When too many indexes fill the connection cache'],answer:1,explanation:'Pool exhaustion manifests as application hangs or errors; causes include long-running transactions, connection leaks, insufficient pool size, or traffic spikes beyond capacity.'},
{id:639,topic:'sql-db',difficulty:'advanced',question:'What is "read-after-write consistency" in distributed databases?',options:['Always reading the most recently written data','A consistency guarantee that after a user writes a record, their subsequent reads will reflect that write — important for user-facing applications but challenging in distributed systems with replicas','A consistency level requiring all nodes to confirm a write before returning','Reading data back after a write to verify accuracy'],answer:1,explanation:'Read-after-write (read-your-writes) consistency guarantees the user sees their own writes immediately; implemented by routing reads to the primary, using session tokens, or sticky sessions to the same replica.'},
{id:640,topic:'sql-db',difficulty:'advanced',question:'What is "database normalization to BCNF" (Boyce-Codd Normal Form)?',options:['A strict version of 3NF that eliminates ALL functional dependencies where the determinant is not a superkey — stricter than 3NF because it handles overlapping candidate key scenarios','A normal form only applicable to large databases','Normalisation that eliminates all NULL values','A normalisation form used only in distributed databases'],answer:0,explanation:'BCNF (3.5NF): every determinant must be a superkey. BCNF is stricter than 3NF — it eliminates functional dependencies that 3NF may miss when a table has multiple overlapping candidate keys.'},
{id:641,topic:'sql-db',difficulty:'beginner',question:'What is a "primary key" in simple terms?',options:['The first column in a table','A unique identifier for each row in a table — no two rows can have the same value and it cannot be NULL','A column that references another table','A column with a default value'],answer:1,explanation:'The primary key uniquely identifies each row; it must be unique and non-NULL. It can be one column or a combination (composite key).'},
{id:642,topic:'sql-db',difficulty:'beginner',question:'What does SELECT COUNT(*) FROM employees return?',options:['The number of columns in the employees table','The number of non-NULL values in the first column','The total number of rows in the employees table, including rows with NULL values','The sum of all numeric columns'],answer:2,explanation:'COUNT(*) counts all rows in the table including those with NULL values in any column, returning the total row count.'},
{id:643,topic:'sql-db',difficulty:'beginner',question:'What is a "schema" in database terminology?',options:['A password-protected database user','The logical container defining database objects (tables, views, indexes, stored procedures) and their structure','A type of backup file','A scheduled maintenance job'],answer:1,explanation:'A schema is the logical blueprint of a database: it defines what tables exist, their columns, data types, constraints, relationships, and other database objects.'},
{id:644,topic:'sql-db',difficulty:'beginner',question:'Which SQL clause is used to sort results in descending order?',options:['ORDER BY col ASC','ORDER BY col DESC','SORT BY col DESC','GROUP BY col DESC'],answer:1,explanation:'ORDER BY col DESC sorts the result set in descending order (Z→A alphabetically, largest→smallest numerically, most recent→oldest for dates).'},
{id:645,topic:'sql-db',difficulty:'beginner',question:'What does the DISTINCT keyword prevent in SELECT results?',options:['NULL values','Sorting of duplicate values','Returning duplicate rows in the result set','Joining on non-indexed columns'],answer:2,explanation:'DISTINCT removes duplicate rows from the result set, ensuring each unique combination of selected column values appears only once.'},
{id:646,topic:'sql-db',difficulty:'beginner',question:'In SQL, what does "DQL" stand for?',options:['Data Query Language (SELECT)','Data Quality Language','Database Query Library','Data Quantification Level'],answer:0,explanation:'DQL (Data Query Language) refers to the SQL SELECT statement used to query and retrieve data from tables. Some SQL classifications treat SELECT as DQL rather than DML.'},
{id:647,topic:'sql-db',difficulty:'beginner',question:'What is the result of dividing by zero in SQL?',options:['Returns NULL','Returns zero','Raises a divide-by-zero error or returns NULL depending on the database','Returns infinity'],answer:2,explanation:'Most databases (SQL Server, MySQL) raise a divide-by-zero error on / 0; PostgreSQL returns an error. Use NULLIF(divisor, 0) to safely return NULL instead of an error.'},
{id:648,topic:'sql-db',difficulty:'beginner',question:'What does "concatenation" mean for strings in SQL?',options:['Sorting strings alphabetically','Joining two or more strings end-to-end into a single string using CONCAT() or the || operator','Splitting a string into multiple parts','Removing duplicates from a string column'],answer:1,explanation:'String concatenation joins multiple string values: CONCAT(\'Hello\', \' \', \'World\') = \'Hello World\'. Standard SQL uses ||; MySQL also supports CONCAT().'},
{id:649,topic:'sql-db',difficulty:'beginner',question:'What is the purpose of the LIMIT clause in MySQL/PostgreSQL?',options:['Limits the number of columns returned','Restricts the number of rows returned by a query, useful for pagination and top-N queries','Limits the size of a VARCHAR column','Sets a maximum for aggregate functions'],answer:1,explanation:'LIMIT n restricts the result set to the first n rows. Combined with OFFSET m, it enables pagination: LIMIT 10 OFFSET 20 returns rows 21–30.'},
{id:650,topic:'sql-db',difficulty:'beginner',question:'What is SQL\'s "three-valued logic" (3VL)?',options:['Three possible data types for a column','SQL boolean logic has three possible truth values: TRUE, FALSE, and UNKNOWN (which occurs when any operand is NULL) — affecting WHERE conditions and CHECK constraints','Three possible states for a transaction','A method for evaluating three-way JOINs'],answer:1,explanation:'Standard Boolean logic has TRUE/FALSE; SQL adds UNKNOWN when NULL is involved in comparisons. WHERE conditions filter only TRUE rows; rows evaluating to UNKNOWN or FALSE are excluded.'},
{id:651,topic:'sql-db',difficulty:'intermediate',question:'In which situation would you use NOT EXISTS instead of NOT IN?',options:['When performance must be maximised at all costs','When the subquery might return NULL values — NOT IN returns no rows if any value in the list is NULL, while NOT EXISTS correctly handles NULLs by checking row existence','When the comparison column has a UNIQUE constraint','When comparing strings'],answer:1,explanation:'NOT IN with NULLs: if the subquery returns any NULL, the entire NOT IN condition evaluates to UNKNOWN and no rows pass. NOT EXISTS uses row existence, not value comparison, so NULLs don\'t affect the outer query.'},
{id:652,topic:'sql-db',difficulty:'intermediate',question:'What is "implicit join" syntax and why is explicit JOIN preferred?',options:['JOIN syntax is called implicit; FROM,WHERE is explicit','The comma-separated table list in FROM with WHERE conditions (old style): SELECT * FROM A, B WHERE A.id = B.fk — explicit JOIN syntax (INNER JOIN ... ON) is preferred for clarity, prevents accidental Cartesian products, and is more readable','Implicit JOINs are faster than explicit JOINs','Explicit JOINs use more database resources'],answer:1,explanation:'Implicit join (FROM A, B WHERE A.id=B.fk) is harder to read and error-prone (omitting the WHERE condition creates a Cartesian product). Explicit JOIN...ON clearly separates join conditions from filter conditions.'},
{id:653,topic:'sql-db',difficulty:'intermediate',question:'What is "database deadlock detection" and how do most databases handle it?',options:['A DBA monitoring tool that alerts on deadlocks','Most RDBMS run background deadlock detection processes that identify circular wait chains and automatically roll back the transaction with the least undo cost (the victim), returning an error to the application','Databases prevent deadlocks by queuing all transactions','Deadlocks are handled by killing all involved transactions'],answer:1,explanation:'Deadlock detectors periodically scan for cycles in the lock wait-for graph; upon finding one, the database selects a victim (minimising undo cost), rolls it back, and notifies the application — which should retry the transaction.'},
{id:654,topic:'sql-db',difficulty:'intermediate',question:'What is "SAVEPOINT" useful for in complex transactions?',options:['Saving the entire database state','Marking a point within a transaction that can be partially rolled back to without aborting the entire transaction — useful for implementing partial retry logic in complex multi-step operations','Saving frequently executed queries','Saving execution plans for reuse'],answer:1,explanation:'SAVEPOINT name allows ROLLBACK TO name to undo only the work done after the savepoint, preserving prior committed steps within the same transaction — reducing retry scope in complex operations.'},
{id:655,topic:'sql-db',difficulty:'intermediate',question:'What is "schema migration" and what tools support it?',options:['Moving a database from one server to another','The process of versioning and applying incremental changes to a database schema over time; supported by tools like Liquibase, Flyway, Alembic, and Rails Migrations','Migrating stored procedures between databases','Changing database vendor while preserving data'],answer:1,explanation:'Schema migrations track DDL changes as versioned scripts; migration tools apply pending migrations in order, enabling reproducible schema evolution, rollbacks, and team synchronisation.'},
{id:656,topic:'sql-db',difficulty:'intermediate',question:'What is "referential integrity violation" and when does it occur?',options:['A violation of database naming conventions','Occurs when a DML operation would leave a FK column value with no matching PK in the referenced table: inserting a child row with a non-existent parent, or deleting a parent row that has children (without CASCADE)','A violation of the UNIQUE constraint','A violation of NOT NULL constraints'],answer:1,explanation:'FK violations occur when data would create orphaned records: INSERT with FK pointing to nonexistent parent, or DELETE of a parent with existing children (when no CASCADE is defined).'},
{id:657,topic:'sql-db',difficulty:'intermediate',question:'What is a "database index hint" and when is it used?',options:['A performance hint in the SQL comment','A directive in the query (USE INDEX, WITH (INDEX), FORCE INDEX) that instructs the optimizer to use a specific index, overriding the optimizer\'s plan — used when the optimizer makes a suboptimal choice','A hint for creating better indexes','An automatic optimizer suggestion in EXPLAIN output'],answer:1,explanation:'Index hints force the optimizer to use a specified index; they bypass the cost-based optimizer\'s decision. Use cautiously — they can become wrong as data changes and prevent optimal plan evolution.'},
{id:658,topic:'sql-db',difficulty:'intermediate',question:'What does "query cost" mean in execution plan analysis?',options:['The financial cost of executing a query','An optimizer estimate of the computational resources (I/O reads, CPU operations, memory) required to execute a query plan — used to compare alternative plans, not directly related to wall-clock time','The network bandwidth consumed by a query','The number of rows a query returns'],answer:1,explanation:'Query cost is the optimizer\'s unit-less estimate of total execution resources; lower cost plans are preferred. Cost estimates may diverge from actual wall-clock time when statistics are stale or estimates are inaccurate.'},
{id:659,topic:'sql-db',difficulty:'intermediate',question:'What is "database connection pooling" configured for in a typical application?',options:['Maximum number of simultaneous database instances','Parameters including min/max pool size, connection timeout, idle timeout, and max lifetime — balancing resource efficiency with concurrency needs','Maximum query execution time','Maximum number of transactions per connection'],answer:1,explanation:'Pool configuration parameters: minIdle (pre-warmed connections), maxSize (peak concurrency support), connectionTimeout (wait before error), idleTimeout (release unused connections), maxLifetime (connection recycling).'},
{id:660,topic:'sql-db',difficulty:'intermediate',question:'In SQL Server, what is a "columnstore index" used for?',options:['Storing columns alphabetically','A special index that stores and compresses data column-by-column instead of row-by-row, dramatically accelerating analytical aggregation queries by reading only the required column segments','An index that only indexes character columns','A type of full-text search index'],answer:1,explanation:'Columnstore indexes (clustered or non-clustered) store data in column segments with high compression ratios, enabling batch mode execution that can be 10–100x faster for aggregation-heavy analytical queries.'},
{id:661,topic:'sql-db',difficulty:'advanced',question:'What is "parallel query execution" and when do databases use it?',options:['Running the same query on multiple databases','Splitting a single query into multiple parallel threads that each process a portion of the data simultaneously, then combining results — used for large data scans, joins, and aggregations on multi-core systems','Running queries on parallel replicas','Executing multiple user queries simultaneously'],answer:1,explanation:'Parallel execution (degree of parallelism) splits work across CPU cores: parallel scans, parallel hash joins, parallel sort — significantly accelerating large analytical queries on appropriate hardware.'},
{id:662,topic:'sql-db',difficulty:'advanced',question:'What is "late binding" in database views vs. "early binding"?',options:['Delayed view creation','Late binding: view definitions are compiled and validated at query time (SQL Server default schemabinding option when not set); early binding (SCHEMABINDING): compiled at view creation time, locking the referenced table structure','Binding views to specific user sessions','Lazy loading in a view context'],answer:1,explanation:'Late binding allows referenced objects to be dropped/modified without invalidating the view (until queried). SCHEMABINDING (early binding) prevents such modifications, ensuring the view always compiles — required for indexed views.'},
{id:663,topic:'sql-db',difficulty:'advanced',question:'What is a "CTI" (Conditional Table Index) pattern, and what is it more commonly known as?',options:['A composite index with a conditional filter','A partial (filtered) index: an index built on a subset of rows satisfying a filter condition, reducing index size and maintenance overhead while improving query performance for that specific subset','A conditional trigger on a table','A CTI is not a standard SQL concept'],answer:1,explanation:'Partial/filtered indexes (CREATE INDEX ... WHERE condition) are smaller and cheaper to maintain than full-table indexes, while providing the same performance benefit for queries that include the filter condition.'},
{id:664,topic:'sql-db',difficulty:'advanced',question:'What is "SQL Server Query Store" and what problem does it solve?',options:['A store for saved SQL scripts','A feature that captures a history of query execution plans and runtime statistics, enabling detection and correction of plan regressions by forcing the previous good plan when performance degrades','A SQL Server repository for stored procedures','A backup of the query execution log'],answer:1,explanation:'Query Store captures a history of plans and metrics per query; it enables automatic plan forcing when a regression is detected (Automatic Plan Correction), and lets DBAs compare plan performance over time.'},
{id:665,topic:'sql-db',difficulty:'advanced',question:'What is "index covering" for queries that use ORDER BY?',options:['An index that covers all DML operations','When an index includes both the WHERE filter columns and the ORDER BY columns, the optimizer can satisfy the sort using index order (avoiding a separate sort operation), further reducing query cost','An index that prevents ORDER BY from changing result order','A covering index that spans multiple tables'],answer:1,explanation:'An index that covers the WHERE conditions AND includes the ORDER BY column allows the database to serve results in index order without a separate sort step, improving query performance significantly.'},
{id:666,topic:'sql-db',difficulty:'advanced',question:'What is the "SELECT FOR UPDATE" statement used for?',options:['Selecting data to be updated later without locking','Placing a pessimistic write lock on selected rows, preventing other transactions from modifying those rows until the current transaction commits or rolls back — used to implement optimistic locking check-and-update patterns safely','Selecting and immediately updating rows in one step','A read-only select with update privileges'],answer:1,explanation:'SELECT ... FOR UPDATE acquires row-level write locks on the returned rows, preventing concurrent modifications. Used when you intend to update the selected rows and need to prevent concurrent changes between the SELECT and UPDATE.'},
{id:667,topic:'sql-db',difficulty:'advanced',question:'What is "lazy evaluation" in SQL window functions?',options:['Evaluating window functions only when the result is needed','Not a standard SQL window function concept — window functions are fully computed for all rows before returning the result set','Caching window function results for reuse','Evaluating window functions in parallel'],answer:1,explanation:'SQL window functions are not lazily evaluated — they are computed for all rows in the window frame as part of query execution before results are returned. "Lazy evaluation" is more relevant to programming languages.'},
{id:668,topic:'sql-db',difficulty:'advanced',question:'What is "index-organized table" (IOT) in Oracle?',options:['A table where all data is stored in an index structure','A table where all data (key and non-key columns) is stored in the primary key B-tree index structure itself, eliminating the separate table heap — providing faster PK lookups but potentially slower full scans and more complex secondary index access','A table organised by index creation order','A temporary table used for index maintenance'],answer:1,explanation:'Oracle IOTs store all row data in the PK index leaf nodes; there is no separate table segment. This provides optimal PK access but increases secondary index cost (secondary indexes store PK values as row pointers instead of physical ROWIDs).'},
{id:669,topic:'sql-db',difficulty:'advanced',question:'What is "segment size estimation" important for in database design?',options:['Estimating the database license cost','Projecting the disk space required for tables and indexes based on estimated row count, row width, and growth rate — informing storage provisioning, index design decisions, and IO subsystem planning','Sizing the database team','Estimating the number of indexes needed'],answer:1,explanation:'Accurate segment sizing prevents storage-related outages, informs table/index design (e.g., choosing smaller data types), and enables appropriate RAID/SSD capacity planning.'},
{id:670,topic:'sql-db',difficulty:'advanced',question:'What is "HTAP" (Hybrid Transactional and Analytical Processing)?',options:['A high-traffic application protocol','A database architecture that supports both OLTP workloads (fast transactions) and OLAP analytical queries on the same dataset and hardware simultaneously, eliminating the need for separate OLTP and DW systems — exemplified by systems like SAP HANA, CockroachDB, and TiDB','A type of NoSQL database','A hybrid cloud database deployment model'],answer:1,explanation:'HTAP databases (SAP HANA, TiDB, SingleStore) handle both transactional and analytical workloads on live data, eliminating ETL pipeline latency and enabling real-time analytics on current operational data.'},
{id:671,topic:'sql-db',difficulty:'beginner',question:'What is the purpose of the GROUP BY clause?',options:['Sort results by a column','Group rows with the same values in specified columns together for aggregate function calculation','Filter rows based on aggregate conditions','Create a temporary table from grouped data'],answer:1,explanation:'GROUP BY groups rows with identical values in the specified columns into summary rows; aggregate functions (SUM, COUNT, AVG, MAX, MIN) then calculate values per group.'},
{id:672,topic:'sql-db',difficulty:'beginner',question:'What does SELECT * mean in SQL?',options:['Select all rows','Select all columns from the specified table(s)','Select only the first row','Select NULL values from all columns'],answer:1,explanation:'SELECT * retrieves all columns from the table(s) in the FROM clause. It is convenient for exploration but discouraged in production code (explicit column lists are preferred for performance and clarity).'},
{id:673,topic:'sql-db',difficulty:'beginner',question:'What is a "transaction" in SQL?',options:['A single SQL statement','A logical unit of work comprising one or more SQL statements that must all succeed or all fail together, maintaining ACID properties','A saved query template','A database replication event'],answer:1,explanation:'A transaction groups multiple SQL statements into an atomic unit: either all operations complete successfully (COMMIT) or all are rolled back (ROLLBACK) if any fails.'},
{id:674,topic:'sql-db',difficulty:'beginner',question:'Which of the following is NOT a valid SQL aggregate function?',options:['COUNT()','SUM()','CONCATENATE()','MAX()'],answer:2,explanation:'CONCATENATE() is not a SQL aggregate function. Valid aggregate functions include COUNT, SUM, AVG, MAX, MIN, and (in some databases) STRING_AGG/GROUP_CONCAT.'},
{id:675,topic:'sql-db',difficulty:'beginner',question:'What is the OFFSET clause used for in pagination queries?',options:['Limits the total rows returned','Skips a specified number of rows before returning the result, enabling pagination: LIMIT 10 OFFSET 20 returns rows 21-30','Offsets column values by a numeric amount','Creates an offset between joins'],answer:1,explanation:'OFFSET n skips the first n rows of the result set; combined with LIMIT/FETCH, it enables page-by-page navigation: page 3 of 10 results = LIMIT 10 OFFSET 20.'},
{id:676,topic:'sql-db',difficulty:'intermediate',question:'What is "SQL injection" testing and what is it designed to find?',options:['Testing that SQL queries inject data correctly','Sending SQL metacharacters and injection payloads through application inputs to verify whether unsanitised inputs allow attackers to manipulate database queries — finding authentication bypass, data exfiltration, and data modification vulnerabilities','Testing that SQL functions work correctly','Performance testing of injection points in queries'],answer:1,explanation:'SQL injection testing submits payloads like \'OR 1=1--, UNION SELECT..., and DROP TABLE to input fields to verify whether the application correctly parameterises queries and prevents malicious SQL execution.'},
{id:677,topic:'sql-db',difficulty:'intermediate',question:'What is "stored procedure execution plan caching"?',options:['Saving stored procedure source code','The database compiles and caches the execution plan for a stored procedure on first execution; subsequent calls reuse the cached plan, avoiding repeated compilation overhead','Caching the stored procedure output for reuse','Creating a snapshot of the stored procedure at creation time'],answer:1,explanation:'Stored procedure plan caching avoids per-execution compilation; however, "parameter sniffing" can cause the cached plan (optimised for the first execution\'s parameters) to be suboptimal for different parameter values.'},
{id:678,topic:'sql-db',difficulty:'intermediate',question:'What is "parameter sniffing" in stored procedures?',options:['Inspecting stored procedure parameters for security vulnerabilities','When the database compiles and caches an execution plan optimised for the first set of parameters passed to a stored procedure, which may be suboptimal for subsequent calls with different parameter values','A technique for detecting SQL injection in stored procedures','When the optimizer sniffs table statistics before executing a procedure'],answer:1,explanation:'Parameter sniffing: the first-call plan may work perfectly for that call\'s data distribution but poorly for other data distributions, causing inconsistent performance. Mitigations: OPTION (RECOMPILE), OPTIMIZE FOR UNKNOWN, local variable substitution.'},
{id:679,topic:'sql-db',difficulty:'intermediate',question:'What is "inline table-valued function" vs "multi-statement table-valued function" in SQL Server?',options:['They are identical','Inline TVFs contain a single SELECT and are inlined by the optimizer like a view (efficient); Multi-statement TVFs populate a table variable with multiple statements and are treated as an opaque black box (optimizer cannot see inside, often leading to poor cardinality estimates)','Multi-statement TVFs are always faster','Inline TVFs require fewer parameters'],answer:1,explanation:'Inline TVFs are effectively parameterised views — the optimizer can inspect and merge their query plan with the calling query. Multi-statement TVFs are treated as a black box, often generating poor estimates and plans.'},
{id:680,topic:'sql-db',difficulty:'intermediate',question:'What is "query folding" in modern data tools (Power Query, etc.) and why is it important for performance?',options:['Folding paper query reports for printing','The ability of a data transformation tool to translate transformation steps into a native SQL query that runs on the source database, rather than pulling all data and transforming it in memory on the client — dramatically reducing data transfer and transformation time','Collapsing multiple queries into one','A technique for folding nested SELECT statements'],answer:1,explanation:'Query folding pushes transformations (filters, joins, aggregations) back to the source database using SQL, leveraging the database\'s optimised execution engine instead of processing all data in the client tool.'},
{id:681,topic:'sql-db',difficulty:'advanced',question:'What is "temporal table" in SQL Server (System-Versioned)?',options:['A table with time-based partitioning','A table with a built-in history table that automatically tracks all row changes over time, enabling as-of queries (FOR SYSTEM_TIME AS OF) to see the table\'s state at any historical timestamp','A table that stores timestamps as primary keys','A temporary table that expires after a set time'],answer:1,explanation:'SQL Server temporal tables (SQL:2011 standard) automatically maintain a companion history table; every UPDATE/DELETE archives the old version with its period columns, enabling time-travel queries.'},
{id:682,topic:'sql-db',difficulty:'advanced',question:'What is "query parallelism" and when does it harm performance?',options:['Running queries on parallel database servers','Parallel query execution can hurt performance when: the dataset is small (overhead exceeds savings), there are many concurrent parallel queries competing for threads, the system has high CPU contention, or memory grants for parallel sort operations cause spills to disk','Parallel queries always improve performance','Parallel queries only work on cloud databases'],answer:1,explanation:'Parallel overhead (thread management, data redistribution) exceeds savings for small queries; MAXDOP = 1 forces serial execution. High-concurrency OLTP systems often prefer serial execution to prevent CPU saturation.'},
{id:683,topic:'sql-db',difficulty:'advanced',question:'What is "index intersection" in query execution?',options:['The area where two indexes overlap','When the optimizer uses two or more non-clustered indexes and performs an intersection (combining their row sets) to satisfy a query, avoiding a full table scan — beneficial when no single covering index exists','When two indexes are created on the same column','An error caused by conflicting index definitions'],answer:1,explanation:'Index intersection combines row sets from multiple non-clustered indexes using bitmap AND operations, potentially satisfying queries that require multiple filter conditions without a single covering index.'},
{id:684,topic:'sql-db',difficulty:'advanced',question:'What is "execution plan forcing" and when should it be used?',options:['Always forcing the optimizer to use the most expensive plan','Manually specifying the execution plan (via hints, stored plan baseline, or Query Store plan forcing) when the optimizer consistently produces a suboptimal plan — used as a last resort after statistics and index remediation','Forcing parallel execution on all queries','Forcing the use of full table scans'],answer:1,explanation:'Plan forcing (OPTION hints, SQL Server Query Store, Oracle SQL Baselines) should be used sparingly: it prevents plan evolution as data changes, but is necessary when the optimizer cannot produce an acceptable plan through normal means.'},
{id:685,topic:'sql-db',difficulty:'advanced',question:'What is "columnstore compression" and how does it work?',options:['Compressing column headers in the schema','Column stores compress each column independently using algorithms optimised for that column\'s data type and cardinality (run-length encoding for low-cardinality, delta encoding for sorted sequences, LZ4/LZO for general data), achieving 5–10x compression vs row stores','Compressing the entire table into a single column','A ZIP compression of the database files'],answer:1,explanation:'Columnstore compression is dramatically more effective than row compression: sorting and delta-encoding sequential values, run-length encoding repeated values, and dictionary encoding low-cardinality strings — enabling I/O and memory efficiency for analytical queries.'},
{id:686,topic:'sql-db',difficulty:'advanced',question:'What is "query rebinding" or "plan invalidation" in PostgreSQL?',options:['Rewriting queries for better performance','When statistics changes, schema changes, or explicit ANALYZE cause the prepared statement\'s cached plan to be invalidated and a new plan to be compiled on the next execution','A technique for binding parameters at runtime','Re-running queries that returned errors'],answer:1,explanation:'PostgreSQL prepared statement plans can be invalidated (replanned) after 5 executions if statistics suggest a generic plan is better, or on explicit DEALLOCATE. Plan invalidation ensures statistics changes trigger replanning.'},
{id:687,topic:'sql-db',difficulty:'advanced',question:'What is "tablespace" in database storage management?',options:['The size limit of a single table','A logical storage container that maps to physical storage locations (datafiles, directories), used to control where database objects are physically stored and enabling separate management of different object types or tenants','A namespace for tables in a schema','A type of partition for large tables'],answer:1,explanation:'Tablespaces (Oracle, PostgreSQL, SQL Server filegroups) map logical database objects to physical storage locations, enabling administrators to control I/O distribution, separate fast/slow storage, and manage growth.'},
{id:688,topic:'sql-db',difficulty:'advanced',question:'What is "autovacuum" in PostgreSQL and why is it critical?',options:['An automatic backup tool','A background daemon that automatically runs VACUUM and ANALYZE on tables when dead tuple accumulation or stale statistics cross configurable thresholds — preventing transaction ID wraparound, reclaiming space, and keeping statistics current','An automatic index creation tool','A tool for automatically defragmenting the database'],answer:1,explanation:'Autovacuum is PostgreSQL\'s background maintenance daemon; without it, dead tuples accumulate (degrading performance), statistics go stale (bad plans), and eventually transaction ID wraparound threatens data integrity.'},
{id:689,topic:'sql-db',difficulty:'advanced',question:'What is "logical replication" vs "physical replication" in PostgreSQL?',options:['Logical is for data; physical is for schema','Physical replication streams WAL at the binary block level (fast, exact copy, same major version); logical replication decodes WAL into logical change records (table-level granularity, supports different versions, enables selective replication of specific tables)','Logical replication is for OLAP; physical for OLTP','They are identical in PostgreSQL'],answer:1,explanation:'Physical (streaming) replication is a byte-for-byte copy (standby must be same PG version). Logical replication streams row-level changes in a decoded format, supporting version-upgrade scenarios and cross-database selective replication.'},
{id:690,topic:'sql-db',difficulty:'advanced',question:'What is "Boyce-Codd Normal Form" (BCNF) different from 3NF?',options:['BCNF and 3NF are identical','BCNF is stricter: every functional dependency X→Y must have X as a superkey. 3NF allows dependencies where Y is a prime attribute (part of a candidate key) — BCNF eliminates this exception, sometimes requiring lossless-join decomposition that sacrifices dependency preservation','BCNF only applies to tables with more than 3 columns','BCNF requires all columns to have the same data type'],answer:1,explanation:'3NF allows X→Y when Y is a prime attribute even if X is not a superkey (to preserve dependencies). BCNF does not allow this exception, providing a stricter guarantee but occasionally making it impossible to preserve all functional dependencies after decomposition.'},
{id:691,topic:'sql-db',difficulty:'beginner',question:'Which SQL keyword creates a new database?',options:['NEW DATABASE','BUILD DATABASE','CREATE DATABASE','INIT DATABASE'],answer:2,explanation:'CREATE DATABASE name creates a new database management system database; in MySQL, PostgreSQL, and SQL Server, this is the standard DDL command.'},
{id:692,topic:'sql-db',difficulty:'beginner',question:'What does the USE statement do in MySQL or SQL Server?',options:['Declares a variable for use in a query','Selects a specific database to use for subsequent SQL statements in the current session','Creates a new table','Grants use permission to a user'],answer:1,explanation:'USE database_name sets the specified database as the active/current database for the session, so subsequent queries target that database without needing to qualify table names.'},
{id:693,topic:'sql-db',difficulty:'beginner',question:'What is a "column" in a relational database table?',options:['A single row of data','A vertical attribute of a table representing a specific piece of information (field) with a defined data type and optional constraints','A single cell in a spreadsheet','An index on the table'],answer:1,explanation:'A column (attribute/field) defines a specific type of data that each row in the table stores — e.g., "first_name" VARCHAR(100), "age" INT, "created_at" TIMESTAMP.'},
{id:694,topic:'sql-db',difficulty:'beginner',question:'What is a "row" in a relational database?',options:['A column of data','A single record (tuple) in a table representing one instance of the entity the table models','The header of a table','A type of index'],answer:1,explanation:'A row (record, tuple) is a horizontal entry in a table, representing one complete instance of the entity: all column values for a single customer, order, product, etc.'},
{id:695,topic:'sql-db',difficulty:'beginner',question:'What is the basic structure of a SELECT statement?',options:['SELECT columns WHERE conditions FROM table','SELECT columns FROM table [WHERE conditions] [ORDER BY columns] [LIMIT n]','FROM table SELECT columns','INSERT columns SELECT FROM table'],answer:1,explanation:'The basic SELECT syntax: SELECT <columns> FROM <table> [WHERE <filter>] [GROUP BY <cols>] [HAVING <filter>] [ORDER BY <cols>] [LIMIT n]. FROM and SELECT are the only mandatory clauses.'},
{id:696,topic:'sql-db',difficulty:'intermediate',question:'What is the difference between DATETIME and TIMESTAMP in MySQL?',options:['They store identical data','DATETIME stores date+time as-is (no timezone conversion, range: 1000-9999); TIMESTAMP stores date+time in UTC (auto-converts to/from session timezone, range: 1970-2038)','TIMESTAMP supports milliseconds; DATETIME does not','DATETIME has a larger range than TIMESTAMP'],answer:1,explanation:'MySQL DATETIME: literal date+time, no timezone, range 1000-9999. TIMESTAMP: stored in UTC, displayed in session timezone, range limited to 2038 (32-bit Unix timestamp). Use DATETIME for birthdays; TIMESTAMP for audit timestamps.'},
{id:697,topic:'sql-db',difficulty:'intermediate',question:'What is "query hint" in SQL and when should it be used?',options:['A SQL comment explaining query purpose','A directive that overrides the query optimizer\'s decisions about access paths, join methods, or parallelism — should be used sparingly as a last resort when the optimizer consistently makes suboptimal choices','An index that hints the optimizer','A debugging comment for stored procedures'],answer:1,explanation:'Query hints (NOLOCK, FORCESEEK, USE INDEX, PARALLEL) override optimizer decisions; use only when you have proven the optimizer is wrong, as hints prevent self-adapting plans as data changes.'},
{id:698,topic:'sql-db',difficulty:'intermediate',question:'What is a "full-text index" used for?',options:['An index covering all columns in a table','A specialised index enabling efficient linguistic searches (keyword search, phrase search, proximity search, fuzzy matching) on large text columns — significantly faster than LIKE \'%keyword%\' pattern matching','An index on all tables in a schema','A type of composite index for text columns'],answer:1,explanation:'Full-text indexes (FTI) tokenise and index text at the word/token level, enabling efficient CONTAINS() / FREETEXT() / @@ tsvector queries for natural language search — orders of magnitude faster than column-scanning LIKE searches.'},
{id:699,topic:'sql-db',difficulty:'intermediate',question:'What is "replication lag" in database replication?',options:['The time it takes to replicate a schema change','The delay between when a write is committed on the primary and when it appears on a replica; excessive lag means replicas serve stale data and failover may lose transactions','The performance overhead caused by replication','The time to set up replication'],answer:1,explanation:'Replication lag in async replication means replicas trail the primary; reads from lagging replicas return stale data. Lag is caused by replica I/O/SQL thread performance, network bandwidth, or heavy primary write volume.'},
{id:700,topic:'sql-db',difficulty:'intermediate',question:'What is the purpose of an "outer join" over an "inner join"?',options:['Outer joins are always faster','Outer joins include unmatched rows from one or both tables (filled with NULLs), enabling queries that need to show all records from one table regardless of whether they have matching records in the related table','Outer joins work on more than two tables','Outer joins perform better than inner joins'],answer:1,explanation:'Use outer joins when you need all rows from one table even without matches: e.g., all customers whether or not they have placed orders (LEFT JOIN customers ON orders.customer_id).'},
{id:701,topic:'sql-db',difficulty:'advanced',question:'What is a "sparse column" in SQL Server?',options:['A column with few distinct values','A column that uses NULL-optimised storage for columns that will be NULL for the majority of rows, using no storage for NULL values but more storage for non-NULL values — useful when a table has many optional attributes','A column with compressed data','A column that is rarely indexed'],answer:1,explanation:'Sparse columns (SQL Server) store no bytes for NULL values (unlike regular columns which use storage even for NULLs) but require 4 extra bytes for non-NULL values — optimal when > 20-40% of rows have NULL.'},
{id:702,topic:'sql-db',difficulty:'advanced',question:'What is "database mirroring" or "Always On Availability Groups" in SQL Server?',options:['A backup copy on the same server','Availability Groups provide synchronous or asynchronous data replication to one or more secondary replicas, with automatic or manual failover, and optionally making secondaries readable — for HA/DR scenarios','A technique for mirroring table structures without data','A synonym for database replication'],answer:1,explanation:'Always On Availability Groups (AOAG) replace deprecated database mirroring; they support multiple readable secondaries, automatic failover, and flexible synchronous/asynchronous modes for HA and disaster recovery.'},
{id:703,topic:'sql-db',difficulty:'advanced',question:'What is "online index rebuild" vs "offline index rebuild" in SQL Server?',options:['Online indexes are in memory; offline are on disk','Online rebuild allows concurrent DML (reads and writes) during the rebuild using additional temporary space; offline rebuild blocks all access to the table during rebuilding — but is faster and uses less space','Offline rebuild uses a backup; online uses live data','There is no difference in modern SQL Server versions'],answer:1,explanation:'Online rebuild (Enterprise Edition) adds an extra version store overhead but allows production traffic to continue. Offline rebuild is faster but locks the table, requiring a maintenance window.'},
{id:704,topic:'sql-db',difficulty:'advanced',question:'What is "database change data capture" (CDC)?',options:['Capturing schema changes only','A feature that reads the transaction log and records all INSERT, UPDATE, and DELETE changes to tracked tables into change tables — enabling downstream consumers to process only the changed data efficiently for ETL, event streaming, and audit','A tool for capturing failed transactions','A backup technique that captures all changes'],answer:1,explanation:'CDC (SQL Server, PostgreSQL pglogical, Debezium) streams row-level changes from the transaction log; downstream systems subscribe to changes without polling the entire table, enabling efficient data integration and event-driven architectures.'},
{id:705,topic:'sql-db',difficulty:'advanced',question:'What is "database sharding key design" and why does key selection matter?',options:['Shard keys are always primary keys','The shard key determines how data is distributed across shards; poor key selection causes hot spots (one shard receiving disproportionate traffic), while a good key provides even distribution and allows queries to target a single shard (shard key predicate filters)','Shard keys are automatically selected by the database','Shard keys can be changed without data migration'],answer:1,explanation:'Shard key choice is critical: high-cardinality keys (customer_id, user_id) distribute evenly; time-based keys cause hot shard writes; natural business keys may have imbalanced distributions — hot spots negate the benefits of sharding.'},
{id:706,topic:'sql-db',difficulty:'advanced',question:'What is "semi-join" and "anti-join" in relational algebra and SQL?',options:['Half-joins and opposite-joins','Semi-join: returns rows from the left table that have at least one matching row in the right table (like EXISTS); Anti-join: returns rows from the left table that have NO matching row in the right table (like NOT EXISTS) — common optimizer transformations for subqueries','Partial joins only','Joins between tables in different schemas'],answer:1,explanation:'Semi-join and anti-join are relational algebra operations that the optimizer uses internally: subqueries with IN/EXISTS are often transformed into semi-joins; NOT IN/NOT EXISTS into anti-joins.'},
{id:707,topic:'sql-db',difficulty:'advanced',question:'What is "index maintenance" and why is it important for query performance?',options:['Creating new indexes when queries are slow','Periodically rebuilding or reorganising fragmented indexes and updating statistics to maintain optimal query performance as data changes through inserts, updates, and deletes','Deleting unused indexes to improve performance','Renaming indexes to match current table structure'],answer:1,explanation:'Index maintenance includes: REBUILD (eliminate fragmentation, update statistics), REORGANIZE (light defragmentation, online), UPDATE STATISTICS (refresh cardinality estimates). Neglected maintenance leads to degraded query performance.'},
{id:708,topic:'sql-db',difficulty:'advanced',question:'What is "late materialisation" in columnar databases?',options:['Materialising views lazily','Deferring the assembly of complete rows until after all filtering predicates have been applied to individual columns, reducing the amount of data moved and processed during query execution','A technique for late-applying indexes','Lazy loading of column data in SQL Server'],answer:1,explanation:'Late materialisation: apply all column predicates independently first, produce a bitmap of qualifying row IDs, then fetch only the needed data for qualifying rows — dramatically reducing I/O in columnar stores for selective queries.'},
{id:709,topic:'sql-db',difficulty:'advanced',question:'What is "recursive query" and what is its primary use case?',options:['A query that runs recursively to improve performance','A query using a recursive CTE or recursive SQL to process hierarchical or graph data (employee-manager chains, bill of materials, path traversal in graph) by iteratively joining a table to its own results until no more rows match','A query with multiple self-joins','A query that calls a stored procedure recursively'],answer:1,explanation:'Recursive CTEs (WITH RECURSIVE in PostgreSQL, standard WITH in SQL Server/Oracle) iterate through hierarchical data: anchor (base case) + recursive member (references the CTE) until the recursion terminates.'},
{id:710,topic:'sql-db',difficulty:'advanced',question:'What is "query vectorisation" in modern analytical databases?',options:['Converting queries to vector graphics','Processing multiple data values (a "vector" of column values) simultaneously using SIMD CPU instructions, enabling batch column operations that are far more efficient than row-at-a-time processing','A technique for running queries on GPU hardware','Representing queries as mathematical vectors'],answer:1,explanation:'Vectorised query engines (DuckDB, Velox, ClickHouse) process column batches of 1,000–10,000 values per CPU instruction using SIMD, achieving order-of-magnitude speedups over tuple-at-a-time interpretation.'},
{id:711,topic:'sql-db',difficulty:'beginner',question:'What is the purpose of the WHERE clause?',options:['Sorts the result set','Filters rows from the result set based on a specified condition','Groups rows into summary sets','Limits the number of returned columns'],answer:1,explanation:'WHERE filters rows before any aggregation: only rows satisfying the WHERE condition are included in the result set or passed to subsequent GROUP BY processing.'},
{id:712,topic:'sql-db',difficulty:'beginner',question:'Which statement correctly describes the HAVING clause?',options:['HAVING is identical to WHERE','HAVING filters groups (formed by GROUP BY) based on aggregate conditions; WHERE filters individual rows before grouping','HAVING is used without GROUP BY','HAVING applies before the SELECT is processed'],answer:1,explanation:'HAVING is a post-aggregation filter: HAVING COUNT(*) > 5 keeps only groups with more than 5 members, applied after GROUP BY has formed the groups.'},
{id:713,topic:'sql-db',difficulty:'beginner',question:'What does "SELECT DISTINCT col1, col2 FROM table" return?',options:['All rows with only col1 and col2 values','All unique combinations of (col1, col2) values — eliminating rows where both col1 AND col2 are identical to another row','Rows where col1 or col2 is NULL','The first distinct value for each group'],answer:1,explanation:'DISTINCT applies to the full combination of selected columns: if you SELECT DISTINCT col1, col2, rows are deduplicated based on the unique (col1, col2) pair, not col1 alone.'},
{id:714,topic:'sql-db',difficulty:'beginner',question:'What does the keyword NULL represent in SQL?',options:['The number 0','An empty string (\'\')','The boolean value FALSE','An unknown or absent value — not equal to anything, including another NULL'],answer:3,explanation:'NULL represents missing, unknown, or not applicable data. NULL != NULL (use IS NULL); any arithmetic with NULL returns NULL; any comparison with NULL returns UNKNOWN.'},
{id:715,topic:'sql-db',difficulty:'beginner',question:'Which SQL command permanently removes a table from the database?',options:['TRUNCATE TABLE','DELETE TABLE','REMOVE TABLE','DROP TABLE'],answer:3,explanation:'DROP TABLE permanently removes the table definition, all rows, indexes, constraints, and associated triggers — it cannot be undone without a backup or transaction rollback.'},
{id:716,topic:'sql-db',difficulty:'intermediate',question:'What is "column aliasing" and how is it used?',options:['Creating a duplicate column in a table','Assigning a temporary name to a column in a query result set using the AS keyword, improving readability and enabling reference in ORDER BY — e.g., SELECT salary * 12 AS annual_salary','Renaming a column permanently in the table','Creating a view with renamed columns'],answer:1,explanation:'Column aliases (AS) rename columns in result sets: calculated expressions benefit most (AS annual_salary instead of "salary * 12"), and some databases require aliases to reference expressions in ORDER BY.'},
{id:717,topic:'sql-db',difficulty:'intermediate',question:'What is an "outer query" in SQL?',options:['A query running outside the database server','The main (outer) SELECT statement in a query that contains a subquery — it uses the subquery\'s result in its WHERE, FROM, or SELECT clause','A query that accesses external data sources','A query with outer joins'],answer:1,explanation:'The outer query is the primary (main) SELECT; the inner (sub) query is nested within it. The outer query uses the inner query\'s result for its filtering or as a derived table.'},
{id:718,topic:'sql-db',difficulty:'intermediate',question:'What is "write-ahead log" (WAL) shipping used for in PostgreSQL high availability?',options:['Shipping logs to a log server for analysis','Continuously transferring WAL files from the primary to standby servers, which replay them to stay in sync — providing hot/warm standby for disaster recovery','A technique for logging all write operations','Shipping database backups to remote storage'],answer:1,explanation:'WAL shipping (log shipping) continuously sends WAL segment files to standby servers; standbys replay WAL to track primary state, enabling failover with potentially minimal data loss.'},
{id:719,topic:'sql-db',difficulty:'intermediate',question:'What is "relational algebra" and why is it foundational to SQL?',options:['Algebra for calculating table sizes','A formal mathematical notation for relational database operations (SELECT σ, PROJECT π, JOIN ⋈, UNION ∪, DIFFERENCE −, CARTESIAN PRODUCT ×) — SQL is based on and maps to relational algebra operations','A graphical modelling language for databases','A mathematical model for database indexing'],answer:1,explanation:'Relational algebra provides the theoretical foundation for SQL: SELECT ↔ σ (filter), PROJECT ↔ π (column selection), JOIN ↔ ⋈, UNION ↔ ∪ etc. Understanding RA explains SQL semantics and optimizer transformations.'},
{id:720,topic:'sql-db',difficulty:'advanced',question:'What is "column cardinality" and how does it affect index design?',options:['The number of columns in a table','The number of distinct values in a column relative to total rows. High cardinality (many unique values) benefits most from indexing; low cardinality (few unique values, e.g., boolean) makes indexes less effective for selective queries','The cardinality of the relationship between tables','The number of rows in a column partition'],answer:1,explanation:'High-cardinality columns (user_id, email) make indexes highly selective and efficient. Low-cardinality columns (status: 2-5 values, gender: M/F) may be better served by bitmap indexes (data warehouses) or conditional filtering.'}
]);
